using System;using System.IO;using System.Linq;using System.Text.Json;using Mono.Cecil;
static class Program
{
 static object Marshal(MarshalInfo m){if(m==null)return null;if(m is ArrayMarshalInfo a)return new{kind=m.GetType().Name,native_type=(int)m.NativeType,element_type=(int)a.ElementType,size=a.Size,size_parameter_index=a.SizeParameterIndex,size_parameter_multiplier=a.SizeParameterMultiplier};if(m is FixedArrayMarshalInfo f)return new{kind=m.GetType().Name,native_type=(int)m.NativeType,element_type=(int)f.ElementType,size=f.Size};if(m is FixedSysStringMarshalInfo s)return new{kind=m.GetType().Name,native_type=(int)m.NativeType,size=s.Size};if(m is CustomMarshalInfo c)return new{kind=m.GetType().Name,native_type=(int)m.NativeType,guid=c.Guid.ToString(),unmanaged_type=c.UnmanagedType,managed_type=c.ManagedType?.FullName,cookie=c.Cookie};if(m is SafeArrayMarshalInfo b)return new{kind=m.GetType().Name,native_type=(int)m.NativeType,element_type=(int)b.ElementType};return new{kind=m.GetType().Name,native_type=(int)m.NativeType};}
 static System.Collections.Generic.IEnumerable<TypeDefinition> Types(TypeDefinition t){yield return t;foreach(var n in t.NestedTypes)foreach(var v in Types(n))yield return v;}
 static int Main(string[] a){using(var m=ModuleDefinition.ReadModule(a[0],new ReaderParameters{ReadingMode=ReadingMode.Deferred})){var types=m.Types.SelectMany(Types).ToArray();var fields=types.SelectMany(t=>t.Fields).Where(f=>f.HasMarshalInfo).Select(f=>new{owner=f.DeclaringType.FullName,name=f.Name,type=f.FieldType.FullName,flags=(int)f.Attributes,token=f.MetadataToken.ToUInt32(),marshal=Marshal(f.MarshalInfo)}).ToArray();var methods=types.SelectMany(t=>t.Methods).Where(x=>x.IsPInvokeImpl).Select(x=>new{owner=x.DeclaringType.FullName,name=x.Name,token=x.MetadataToken.ToUInt32(),@return=x.ReturnType.FullName,flags=(int)x.Attributes,impl_flags=(int)x.ImplAttributes,pinvoke=new{module=x.PInvokeInfo.Module.Name,entry=x.PInvokeInfo.EntryPoint,attributes=(int)x.PInvokeInfo.Attributes},return_flags=(int)x.MethodReturnType.Attributes,return_marshal=Marshal(x.MethodReturnType.MarshalInfo),parameters=x.Parameters.Select(p=>new{sequence=p.Index+1,name=p.Name,type=p.ParameterType.FullName,flags=(int)p.Attributes,marshal=Marshal(p.MarshalInfo)})}).ToArray();File.WriteAllText(a[1],JsonSerializer.Serialize(new{schema="official-sdk-compiled-marshal-records/v1",assembly=m.Assembly.Name.FullName,fields,methods},new JsonSerializerOptions{WriteIndented=true}));}return 0;}
}
